'use strict';
const C=POSCore,$=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+(n/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const date=s=>new Date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const defaults={business:'UBeer Wholesale',address:'',phone:'',footer:'Thank you for your business.',extra:'',showBarcode:false,showNotes:true,defaultSugarTax:0,defaultSugarRateMicros:0};
let phoneSaleView='products';
let db,page='pos',category='All products',query='',invoiceQuery='',productQuery='',reportFrom='',reportTo='',toastTimer;
try{const saved=window.NativePOS?NativePOS.load():localStorage.getItem('ubeer-pos-v1');db=saved?JSON.parse(saved):null;}catch(e){alert('Saved data could not be opened. Close the app before making changes.');throw e;}
if(!db)db={version:1,products:[],invoices:[],draft:null,settings:{...defaults},nextNumber:1001};
db.settings={...defaults,...db.settings};normalizeCategories(db);normalizeCustomers(db);
function persist(){try{const json=JSON.stringify(db);if(window.NativePOS){if(!NativePOS.save(json))throw Error('Storage failed');}else localStorage.setItem('ubeer-pos-v1',json);return true;}catch(e){alert('Changes could not be saved. Check device storage and keep this app open.');return false;}}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3200);}
function blankInvoice(){return {id:uid(),number:null,created:new Date().toISOString(),updated:new Date().toISOString(),customer:{name:'',phone:'',email:'',address:'',taxId:''},lines:[],payments:[],notes:'',finalized:false,history:[]};}
if(!db.draft)db.draft=blankInvoice();
let current=db.draft;
function saveCurrent(action){current.updated=new Date().toISOString();if(action)current.history.push({at:current.updated,action});return persist();}
function closeDialog(){
 $('modal-overlay').hidden=true;$('dialog').open=false;
 document.body.classList.remove('modal-open');document.querySelector('.shell')?.removeAttribute('inert');
}
function modal(title,body,actions=''){
 clearTimeout(scanTimer);document.activeElement?.blur();
 $('dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button aria-label="Close dialog" onclick="closeDialog()">✕</button></div><div class="dialog-body">${body}</div>${actions}`;
 prepareNumberInputs($('dialog-content'));$('dialog').open=true;$('modal-overlay').hidden=false;
 document.body.classList.add('modal-open');document.querySelector('.shell')?.setAttribute('inert','');
 const scrollBody=$('dialog-content').querySelector('.dialog-body');if(scrollBody)scrollBody.scrollTop=0;
 $('dialog-content').querySelector('.dialog-head button')?.focus({preventScroll:true});
}
function focusScan(){}
function navIcon(name){
 const paths={
 pos:'<path d="M3 3h2l2.5 12h11l2-8H6"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',
 products:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Z"/><path d="m3 8 9 5 9-5M12 13v9M7.5 5.5l9 5"/>',
 invoices:'<path d="M6 3h9l4 4v14H6V3Z"/><path d="M14 3v5h5M9 12h7M9 16h7"/>',
 customers:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',
 reports:'<path d="M3 3v18h18M7 17v-5M12 17V8M17 17V5"/>',
 settings:'<path d="m9 3-.7 2.3-2 .9L4 5.7 2.5 8.3 4.3 10v2l-1.8 1.7L4 16.3l2.3-.5 2 .9L9 19h3l.7-2.3 2-.9 2.3.5 1.5-2.6-1.8-1.7v-2l1.8-1.7L17 5.7l-2.3.5-2-.9L12 3H9Z"/><circle cx="10.5" cy="11" r="3"/>'
 };
 return `<svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[name]}</svg>`;
}
function render(){const names={pos:'Point of sale',products:'Product catalog',invoices:'Invoices',customers:'Customers',reports:'Sales reports',settings:'Receipt, devices & cloud backup'};$('title').textContent=names[page];$('nav').innerHTML=[['pos','Point of sale'],['products','Products'],['invoices','Invoices'],['customers','Customers'],['reports','Sales reports'],['settings','Settings']].map(([p,label])=>`<button class="${page===p?'active':''}" onclick="navigate('${p}')" aria-label="${label}" title="${label}" ${page===p?'aria-current="page"':''}>${navIcon(p)}<span class="nav-text">${label}</span></button>`).join('');({pos:renderPos,products:renderProducts,invoices:renderInvoices,customers:renderCustomers,reports:renderReports,settings:renderSettings}[page])();}
function navigate(p){clearTimeout(scanTimer);page=p;query='';render();}
function newSale(){if(current===db.draft&&(current.lines.length||current.customer.name)&&!confirm('Discard the unfinished sale and start a new one?'))return;db.draft=blankInvoice();current=db.draft;phoneSaleView='products';page='pos';query='';persist();render();focusScan();}
function clearOrder(){if(!current.lines.length)return;if(!confirm('Remove all items from this order? Customer information and recorded payments will remain.'))return;clearTimeout(scanTimer);current.lines=[];query='';saveCurrent('Cleared all order items');renderPos();toast('Order items cleared');}
function renderPos(){const t=C.totals(current);$('content').innerHTML=`<section class="panel sale-workspace"><div class="pos-grid"><section class="panel catalog-panel"><div class="panel-head"><div><h2>Find your products</h2><div class="muted">Scan, search, or select a product to start selling.</div></div><button onclick="productEditor()">＋ Product</button></div><div class="panel-body"><div class="search-wrap"><input id="scan" class="scan" placeholder="⌕  Scan barcode or type a product name…" aria-label="Scan barcode or search product" autocomplete="off" value="${esc(query)}" oninput="scanInput(this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault();submitScan()}"><button class="camera-button" type="button" title="Scan barcode with camera" aria-label="Scan barcode with camera" onclick="cameraScan()">${cameraIcon()}</button><div id="suggestions"></div></div><div class="hint">Exact barcode or unique exact name adds automatically. Similar names show choices.</div><div class="filters">${['All products',...db.categories].map((c,i)=>`<button class="${category===c?'selected':''}" onclick="selectCategory(${i})">${esc(c)}</button>`).join('')}<button onclick="categoryManager()">＋ Category</button></div><div class="products" id="product-grid"></div></div></section><section class="panel cart-panel"><div class="panel-head"><div><h2>${current.number?'Invoice #'+current.number:'Current sale'}</h2><div class="muted">${current.finalized?'Saved invoice · changes save immediately':'Build your wholesale order'}</div></div><div class="cart-header-actions"><span class="badge">${t.packs} packs</span><button class="remove" onclick="clearOrder()" ${!current.lines.length?'disabled':''}>Clear order</button></div></div><div class="panel-body"><button class="wide" onclick="customerEditor()">♙ ${current.customer.name?esc(current.customer.name):'Add customer information'} <span class="muted">✎</span></button><div id="cart-lines">${current.lines.length?current.lines.map((l,i)=>`<div class="cart-line"><div class="line-top"><div><strong>${esc(l.name)}</strong><div class="muted">${l.pack} × ${esc(l.volume)} · ${money(l.price)} / pack</div></div><strong>${money(l.price*l.qty)}</strong></div><div class="line-actions"><button aria-label="Decrease quantity" onclick="changeQty(${i},${l.qty-1})">−</button><input aria-label="Quantity for ${esc(l.name)}" type="number" min="1" step="1" value="${l.qty}" onchange="changeQty(${i},this.value)"><button aria-label="Increase quantity" onclick="changeQty(${i},${l.qty+1})">＋</button><button title="Edit price" aria-label="Edit price for ${esc(l.name)}" onclick="priceEditor(${i})">✎ Price</button><button class="remove" aria-label="Remove ${esc(l.name)}" onclick="removeLine(${i})">✕</button></div></div>`).join(''):'<div class="empty"><div class="empty-symbol">▧</div>Your cart is ready.<br><small>Add a product to create an invoice.</small></div>'}</div><button class="wide" onclick="notesEditor()">${current.notes?'✎ Edit invoice notes':'＋ Invoice notes'}</button></div><div class="totals"><div class="total-row"><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div class="total-row"><span>Soda sugar tax</span><span>${money(t.tax)}</span></div><div class="total-row"><span>Sales tax</span><span>${money(t.salesTax)}</span></div><div class="total-row"><span>Total items</span><span>${t.units} units / ${t.packs} packs</span></div><div class="total-row grand"><span>Total</span><span>${money(t.total)}</span></div><div class="total-row"><span>Amount paid</span><span>${money(t.paid)}</span></div><div class="total-row balance"><span>${t.credit?'Customer credit':'Balance due'}</span><span>${money(t.credit||t.balance)}</span></div><button class="wide" onclick="paymentEditor()" ${!current.lines.length?'disabled':''}>＋ Record payment</button><button class="wide primary" onclick="${current.finalized?'previewInvoice()':'finalizeInvoice()'}" ${!current.lines.length?'disabled':''}>${current.finalized?'Preview & print invoice':'Finalize invoice'} →</button></div></section></div></section>`;renderProductGrid();prepareNumberInputs(document);}
function renderFilters(){document.querySelectorAll('.filters button').forEach(b=>b.classList.toggle('selected',b.textContent===category));}
function renderProductGrid(){const products=db.products.filter(p=>(category==='All products'||p.category===category)&&(!query||C.norm(p.name).includes(C.norm(query))||p.barcode.includes(query)));$('product-grid').innerHTML=products.length?products.map(p=>`<div class="product"><button class="product-select" onclick="addProduct('${p.id}')" aria-label="Add ${esc(p.name)} to cart"><div class="art">${p.category==='Beer'?'🍺':p.category==='Soda'?'🥤':p.category==='Water'?'💧':'📦'}</div><strong>${esc(p.name)}</strong><div class="muted">${p.pack} pack · ${esc(p.volume)}</div><div class="price">${money(p.price)}<span class="plus">＋</span></div></button>${productMenu(p)}</div>`).join(''):`<div class="empty" style="grid-column:1/-1"><div class="empty-symbol">📦</div>${db.products.length?'No matching products.':'Your catalog starts here.'}<br><small>${db.products.length?'Try another name or category.':'Add your first product and save its barcode for future scans.'}</small><br><button style="margin-top:15px" onclick="productEditor(null,query)">＋ Add product</button></div>`;}
let scanTimer;
function scanInput(value){clearTimeout(scanTimer);query=value;renderProductGrid();const result=C.lookup(db.products,value);$('suggestions').innerHTML=value?`<div class="suggestions">${result.matches.length?result.matches.map(p=>`<button onclick="addProduct('${p.id}')"><strong>${esc(p.name)}</strong><div class="muted">${p.pack} × ${esc(p.volume)} · ${money(p.price)} · ${esc(p.barcode)}</div></button>`).join(''):`<button onclick="productEditor(null,query)">No match. Save a new product for “${esc(value)}” →</button>`}</div>`:'';if(result.exact.length===1)scanTimer=setTimeout(()=>{const r=C.lookup(db.products,query);if(r.exact.length===1)addProduct(r.exact[0].id);},350);}
function submitScan(){clearTimeout(scanTimer);const r=C.lookup(db.products,query);if(r.exact.length===1)addProduct(r.exact[0].id);else if(r.matches.length===1)addProduct(r.matches[0].id);else if(!r.matches.length&&query)productEditor(null,query);else if(query)toast('Select the correct product from the matches.');}
function addProduct(id){const savedScroll=window.scrollY||0;clearTimeout(scanTimer);document.activeElement?.blur();const p=db.products.find(x=>x.id===id);if(!p)return;const snapshot=C.makeLine(p);const line=current.lines.find(l=>l.productId===id&&l.price===p.price&&l.sugarTax===(p.soda?p.sugarTax:0)&&l.name===p.name&&l.pack===p.pack&&l.volume===p.volume&&(l.salesTaxBps||0)===snapshot.salesTaxBps&&(l.sugarRateMicros??null)===(snapshot.sugarRateMicros??null)&&(l.ounces||0)===snapshot.ounces);if(line)line.qty++;else current.lines.push(snapshot);query='';saveCurrent('Added '+p.name);renderPos();window.scrollTo?.({top:savedScroll,behavior:'instant'});toast(p.name+' added');}
function changeQty(i,value){const n=Number(value);if(!Number.isSafeInteger(n)||n<1||n>100000){toast('Quantity must be 1–100,000 whole packs.');renderPos();return;}current.lines[i].qty=n;saveCurrent('Changed quantity for '+current.lines[i].name);renderPos();}
function removeLine(i){if(current.finalized&&!confirm('Remove this item from the finalized invoice? Totals and balance will update.'))return;const l=current.lines.splice(i,1)[0];saveCurrent('Removed '+l.name);renderPos();}
function priceEditor(i){const l=current.lines[i];modal('Change cart price',`<p class="muted">${esc(l.name)} · Price per pack for this invoice.</p><label for="price">Price per pack ($)</label><input id="price" type="number" min="0" step="0.01" value="${(l.price/100).toFixed(2)}">`,`<div class="actions"><button onclick="closeDialog()">Cancel</button><button class="primary" onclick="savePrice(${i})">Save price</button></div>`);}
function savePrice(i){try{current.lines[i].price=C.cents($('price').value);saveCurrent('Changed price for '+current.lines[i].name);closeDialog();renderPos();}catch(e){toast(e.message);}}
function customerEditor(customerId=null,databaseOnly=false){const c=databaseOnly?(db.customers.find(c=>c.id===customerId)||{name:'',phone:'',email:'',address:'',taxId:''}):current.customer;modal('Customer information',`<button class="wide" onclick="customerPicker()">♙ Find previous customer</button><p class="muted">Customer contact details appear on the invoice. Tax ID is saved for your records and omitted from receipts.</p><label for="customer-name">Customer / business name</label><input id="customer-name" value="${esc(c.name)}"><div class="form-row"><div><label for="customer-phone">Phone</label><input id="customer-phone" type="tel" value="${esc(c.phone)}"></div><div><label for="customer-email">Email</label><input id="customer-email" type="email" value="${esc(c.email)}"></div></div><label for="customer-tax-id">Customer Tax ID (optional)</label><input id="customer-tax-id" type="text" maxlength="80" value="${esc(c.taxId||'')}" placeholder="Enter customer tax ID"><label for="customer-address">Billing / delivery address</label><textarea id="customer-address">${esc(c.address)}</textarea>`,`<div class="actions"><button onclick="closeDialog()">Cancel</button><button class="primary" onclick="saveCustomer(${customerId?"'"+customerId+"'":'null'},${databaseOnly})">Save customer</button></div>`);}
function saveCustomer(customerId=null,databaseOnly=false){
 const details={name:$('customer-name').value.trim(),phone:$('customer-phone').value.trim(),email:$('customer-email').value.trim(),address:$('customer-address').value.trim(),taxId:$('customer-tax-id').value.trim()};
 if(!details.name){toast('Enter the customer or business name.');return;}
 let record=db.customers.find(c=>c.id===(customerId||(!databaseOnly?current.customerId:null)));
 if(!record)record=db.customers.find(c=>customerIdentity(c)===customerIdentity(details));
 if(record)Object.assign(record,details,{updated:new Date().toISOString()});
 else{record={id:uid(),...details,updated:new Date().toISOString()};db.customers.push(record);}
 if(!databaseOnly){current.customer={...details};current.customerId=record.id;saveCurrent('Updated customer');}
 else persist();
 closeDialog();if(databaseOnly)render();else renderPos();toast('Customer saved');
}
function notesEditor(){modal('Invoice notes',`<label for="notes">Notes</label><textarea id="notes">${esc(current.notes)}</textarea>`,`<div class="actions"><button class="primary" onclick="current.notes=$('notes').value;saveCurrent('Updated notes');closeDialog();renderPos()">Save notes</button></div>`);}
function paymentEditor(){const t=C.totals(current);modal('Record a payment',`<div class="notice">Invoice total <strong>${money(t.total)}</strong> · Balance due <strong>${money(t.balance)}</strong>${t.credit?' · Customer credit '+money(t.credit):''}</div><label for="payment">Payment amount ($)</label><input id="payment" type="number" min="0.01" step="0.01" value="${(t.balance/100).toFixed(2)}" oninput="paymentPreview()"><label for="method">Payment method</label><select id="method"><option>Cash</option><option>Card (external terminal)</option><option>Bank transfer</option><option>Check</option></select><label for="reference">Reference / note</label><input id="reference"><div class="notice" id="payment-preview">Remaining balance: ${money(t.balance)}</div><p class="muted">Records payments received. Card charging is handled by your external payment terminal.</p>${current.payments.map(p=>`<div class="total-row"><span>${date(p.at)} · ${esc(p.method)}</span><strong>${money(p.amount)}</strong></div>`).join('')}`,`<div class="actions"><button onclick="closeDialog()">Cancel</button><button class="primary" onclick="savePayment()">Record payment</button></div>`);}
function paymentPreview(){try{const t=C.totals(current),amount=C.cents($('payment').value);$('payment-preview').textContent=amount>t.balance?'Payment exceeds balance by '+money(amount-t.balance):'Remaining balance: '+money(t.balance-amount);}catch(e){$('payment-preview').textContent='Enter a valid payment amount.';}}
function savePayment(){try{const amount=C.cents($('payment').value);if(amount<=0||amount>C.totals(current).balance)throw Error('Payment must be greater than zero and no more than the balance due.');current.payments.push({id:uid(),amount,method:$('method').value,reference:$('reference').value.trim(),at:new Date().toISOString()});saveCurrent('Recorded payment '+money(amount));closeDialog();renderPos();toast('Payment saved. Balance updated.');}catch(e){toast(e.message);}}
function finalizeInvoice(){if(!current.lines.length)return;if(!current.customer.name.trim()){toast('Add the customer name before finalizing.');customerEditor();return;}current.number=db.nextNumber++;current.finalized=true;db.invoices.push(current);db.draft=blankInvoice();saveCurrent('Finalized invoice');renderPos();previewInvoice();}
function productEditor(id=null,scanned=''){clearTimeout(scanTimer);const p=id?db.products.find(x=>x.id===id):{name:'',barcode:/^[0-9]+$/.test(scanned)?scanned:'',price:0,pack:24,volume:'',category:'Beer',soda:false,sugarTax:0,sugarRateMicros:db.settings.defaultSugarRateMicros,ounces:0,salesTaxBps:0};modal(id?'Edit product':'New product',`<label for="product-name">Product name *</label><input id="product-name" value="${esc(p.name||(!p.barcode?scanned:''))}"><label for="barcode">Barcode</label><input id="barcode" value="${esc(p.barcode)}" placeholder="Scan or type a barcode" autocomplete="off"><button type="button" class="wide" onclick="cameraScan('product')">${cameraIcon()} Scan barcode with camera</button><div class="hint">Save this barcode once. Future scans add the product to the cart.</div><div class="form-row"><div><label for="product-price">Price per pack ($) *</label><input id="product-price" type="number" min="0" step="0.01" value="${(p.price/100).toFixed(2)}"></div><div><label for="pack">Units per pack *</label><input id="pack" type="number" min="1" step="1" value="${p.pack}"></div></div><div class="form-row"><div><label for="volume">Volume per unit *</label><input id="volume" placeholder="e.g. 355 mL / 12 fl oz" value="${esc(p.volume)}"></div><div><label for="category">Category</label><select id="category" onchange="$('soda').checked=this.value==='Soda'">${db.categories.map(c=>`<option value="${esc(c)}" ${p.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div></div><div class="category-create"><input id="new-category" aria-label="New category name" placeholder="New category name"><button type="button" onclick="addCategory(true)">＋ Category</button></div><div class="check" style="margin-top:20px"><input type="checkbox" id="soda" ${p.soda?'checked':''}><label for="soda">Apply soda sugar tax</label></div><div class="form-row"><div><label for="sugar-tax">Sugar tax per US fl oz ($)</label><input id="sugar-tax" type="number" min="0" step="0.000001" value="${((p.sugarRateMicros??(p.sugarTax&&(p.ounces||C.ounces(p.volume))?Math.round(p.sugarTax*10000/(p.pack*(p.ounces||C.ounces(p.volume)))):0))/1000000).toFixed(6)}"></div><div><label for="ounces">US fluid ounces per unit</label><input id="ounces" type="number" min="0" step="0.000001" value="${p.ounces||C.ounces(p.volume)||''}"></div></div><label for="sales-tax">Sales tax (%)</label><input id="sales-tax" type="number" min="0" max="100" step="0.01" value="${((p.salesTaxBps||0)/100).toFixed(2)}"><p class="muted">Sugar tax = rate × ounces per unit × units per pack × packs. Sales tax applies to the item price before sugar tax. Saved invoice items keep their original tax rates.</p>`,`<div class="actions"><button onclick="closeDialog()">Cancel</button><button class="primary" onclick="saveProduct(${id?"'"+id+"'":'null'})">Save product</button></div>`);$('barcode').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('product-name').focus();}});}
function saveProduct(id){try{const p={id:id||uid(),name:$('product-name').value.trim(),barcode:$('barcode').value.trim(),price:C.cents($('product-price').value),pack:Number($('pack').value),volume:$('volume').value.trim(),category:$('category').value,soda:$('soda').checked,sugarTax:0,sugarRateMicros:C.rate($('sugar-tax').value),ounces:Number($('ounces').value)||C.ounces($('volume').value),salesTaxBps:C.salesRate($('sales-tax').value)};p.sugarTax=Math.round(p.sugarRateMicros*p.ounces*p.pack/10000);C.validateProduct(p,db.products);if(!p.volume)throw Error('Enter the volume per unit for receipts.');if(id)db.products[db.products.findIndex(x=>x.id===id)]=p;else db.products.push(p);persist();closeDialog();query='';render();toast('Product saved. Its barcode is ready to scan.');}catch(e){toast(e.message);}}
function renderProducts(){$('content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Your product catalog</h2><div class="muted">${db.products.length} products · Saved barcodes and wholesale pack prices</div></div><div class="catalog-actions"><button onclick="categoryManager()">Categories</button><button class="primary" onclick="productEditor()">＋ Add product</button></div></div><div class="panel-body"><input placeholder="Search products or barcodes…" aria-label="Search catalog" value="${esc(productQuery)}" oninput="productQuery=this.value;renderProductTable()"></div><div id="product-table"></div></section>`;renderProductTable();}
function renderProductTable(){const rows=db.products.filter(p=>C.norm(p.name+' '+p.barcode).includes(C.norm(productQuery)));$('product-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Product</th><th>Barcode</th><th>Pack / volume</th><th>Price</th><th>Sugar tax / oz</th><th>Sales tax</th><th>Actions</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="muted">${esc(p.category)}</div></td><td>${esc(p.barcode||'—')}</td><td>${p.pack} × ${esc(p.volume)}</td><td>${money(p.price)}</td><td>${sugarRateLabel(p)}</td><td>${((p.salesTaxBps||0)/100).toFixed(2)}%</td><td>${productMenu(p,true)} <button class="danger" onclick="deleteProduct('${p.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No products found. Add a product to start selling.</div>';}
function deleteProduct(id){if(!confirm('Remove this product from the catalog? Existing cart and invoice items will be preserved.'))return;db.products=db.products.filter(p=>p.id!==id);closeProductMenus();closeDialog();persist();render();toast('Product removed');}
function status(i){const t=C.totals(i);return t.credit?'Credit due':t.balance===0?'Paid':t.paid?'Partially paid':'Unpaid';}
function renderInvoices(){$('content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Invoice history</h2><div class="muted">Reopen any invoice to add items, change prices, or record payments.</div></div><span class="badge">${db.invoices.length} invoices</span></div><div class="panel-body"><input aria-label="Search invoices" placeholder="Search invoice number or customer…" value="${esc(invoiceQuery)}" oninput="invoiceQuery=this.value;renderInvoiceTable()"></div><div id="invoice-table"></div></section>`;renderInvoiceTable();}
function renderInvoiceTable(){const rows=db.invoices.filter(i=>C.norm(i.number+' '+i.customer.name).includes(C.norm(invoiceQuery))).slice().reverse();$('invoice-table').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Status</th><th>Total</th><th>Balance</th><th>Actions</th></tr></thead><tbody>${rows.map(i=>{const t=C.totals(i);return `<tr><td><strong>#${i.number}</strong><div class="muted">${date(i.created)}</div></td><td>${esc(i.customer.name)}</td><td><span class="badge ${t.balance?'warning':''}">${status(i)}</span></td><td>${money(t.total)}</td><td>${t.credit?'Credit '+money(t.credit):money(t.balance)}</td><td><button onclick="openInvoice('${i.id}')">Open / edit</button> <button onclick="openInvoice('${i.id}',true)">Print</button> <button class="danger" onclick="deleteInvoice('${i.id}')">Delete</button></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty">No invoices found. Finalize a sale to save an invoice here.</div>';}
function openInvoice(id,print=false){phoneSaleView='cart';current=db.invoices.find(i=>i.id===id);page='pos';query='';render();if(print)previewInvoice();else focusScan();}
function deleteInvoice(id){const i=db.invoices.find(x=>x.id===id);if(!confirm('Permanently delete invoice #'+i.number+' and its recorded payments? Sales reports will update.'))return;db.invoices=db.invoices.filter(x=>x.id!==id);if(current.id===id)current=db.draft;persist();renderInvoices();toast('Invoice deleted');}
function receiptMarkup(i){const s=db.settings,t=C.totals(i),c=i.customer;return `<article class="receipt"><div class="receipt-head"><div><h1>${esc(s.business)}</h1><div style="white-space:pre-wrap">${esc(s.address)}</div><div>${esc(s.phone)}</div></div><div><h2>INVOICE #${i.number||'DRAFT'}</h2><p>${date(i.created)}</p><strong>${status(i)}</strong></div></div><h3>Bill to</h3><strong>${esc(c.name||'Customer not entered')}</strong><div style="white-space:pre-wrap">${esc(c.address)}</div><div>${esc(c.phone)} ${esc(c.email)}</div><table><thead><tr><th>Item / pack size / volume</th><th>Packs</th><th>Price / pack</th><th>Sugar tax</th><th>Sales tax</th><th>Amount</th></tr></thead><tbody>${i.lines.map(l=>`<tr><td><strong>${esc(l.name)}</strong><div>${l.pack} units × ${esc(l.volume)}</div>${s.showBarcode&&l.barcode?'<small>Barcode: '+esc(l.barcode)+'</small>':''}</td><td>${l.qty}</td><td>${money(l.price)}</td><td>${money(C.lineSugar(l))}</td><td>${money(C.lineSales(l))}</td><td>${money(l.price*l.qty+C.lineSugar(l)+C.lineSales(l))}</td></tr>`).join('')}</tbody></table><p><strong>Total items: ${t.units} individual units · ${t.packs} packs · ${i.lines.length} line items</strong></p><div class="receipt-summary"><div class="total-row"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div><div class="total-row"><span>Soda sugar tax</span><strong>${money(t.tax)}</strong></div><div class="total-row"><span>Sales tax</span><strong>${money(t.salesTax)}</strong></div><div class="total-row grand"><span>Total amount</span><strong>${money(t.total)}</strong></div><div class="total-row"><span>Paid</span><strong>${money(t.paid)}</strong></div><div class="total-row"><span>Balance due</span><strong>${money(t.balance)}</strong></div>${t.credit?'<div class="total-row"><span>Customer credit / refund due</span><strong>'+money(t.credit)+'</strong></div>':''}</div>${i.payments.length?'<h3>Payments received</h3>'+i.payments.map(p=>'<p>'+date(p.at)+' · '+esc(p.method)+' · '+money(p.amount)+(p.reference?' · '+esc(p.reference):'')+'</p>').join(''):''}${s.showNotes&&i.notes?'<p style="white-space:pre-wrap"><strong>Notes:</strong> '+esc(i.notes)+'</p>':''}${s.extra?'<p style="white-space:pre-wrap">'+esc(s.extra)+'</p>':''}<div class="footer">${esc(s.footer)}</div></article>`;}
function previewInvoice(){modal('Invoice preview',receiptMarkup(current),`<div class="actions"><button onclick="closeDialog()">Continue editing</button><button class="primary" onclick="printInvoice()">▧ Print invoice</button></div>`);}
function printInvoice(){if(!current.customer.name){toast('Add customer information before printing.');closeDialog();customerEditor();return;}const markup=receiptMarkup(current),html=`<!doctype html><html><head><meta charset="utf-8"><style>body{font:12px Arial;color:#222;padding:24px}.receipt-head{display:flex;justify-content:space-between;margin-bottom:25px}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{text-align:left;padding:10px 5px;border-bottom:1px solid #ddd}tr{break-inside:avoid}thead{display:table-header-group}h1{font-size:24px;margin:0 0 8px}h2{font-size:17px}h3{font-size:14px}.receipt-summary{margin-left:auto;max-width:270px}.total-row{display:flex;justify-content:space-between;margin:12px 0}.grand{font-size:18px;border-top:1px solid #ccc;padding-top:10px}.footer{white-space:pre-wrap;border-top:1px solid #ddd;padding-top:15px;margin-top:25px}@page{margin:12mm}</style></head><body>${markup}</body></html>`;if(window.NativePOS){NativePOS.printInvoice(html,'Invoice '+current.number);}else{let area=$('print-only');if(!area){area=document.createElement('div');area.id='print-only';document.body.append(area);}area.style.display='none';area.innerHTML=markup;window.print();}}
function reportInvoices(){return db.invoices.filter(i=>{const local=new Date(i.created),d=[local.getFullYear(),String(local.getMonth()+1).padStart(2,'0'),String(local.getDate()).padStart(2,'0')].join('-');return (!reportFrom||d>=reportFrom)&&(!reportTo||d<=reportTo);});}
let reportTab='summary';
function reportPreset(preset){const now=new Date(),start=new Date(now);if(preset==='all'){reportFrom='';reportTo='';}else{if(preset==='week')start.setDate(start.getDate()-6);if(preset==='month')start.setDate(1);reportFrom=POSReports.day(start);reportTo=POSReports.day(now);}renderReports();}
function reportTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="empty">No activity in this date range.</div></td></tr>`}</tbody></table></div>`;}
function renderReports(){
 const r=POSReports.summarize(db.invoices,C,reportFrom,reportTo),t=r.totals;
 const metric=(label,value,note)=>`<section class="panel metric"><div class="label">${label}</div><div class="value">${value}</div><div class="muted">${note}</div></section>`;
 const details=[['Net item sales',t.subtotal],['Sales tax',t.salesTax],['Soda sugar tax',t.tax],['Total invoice sales',t.total],['Paid on selected invoices',t.paid],['Outstanding balance',t.balance],['Customer credit',t.credit]];
 const paymentTable=reportTable(['Payment method','Payments','Amount recorded'],r.payments.map(p=>[esc(p.name),p.count,money(p.amount)]));
 const itemTable=reportTable(['Item / pack size','Packs','Units','Net sales'],r.items.map(p=>[`${esc(p.name)}<div class="muted">${p.pack} × ${esc(p.volume)}</div>`,p.packs,p.units,money(p.sales)]));
 // Combine long date ranges by month so the chart remains usable on a phone.
 const buckets=new Map();for(const d of r.days){const label=r.days.length>31?d.day.slice(0,7):d.day;const b=buckets.get(label)||{label,sales:0,orders:0};b.sales+=d.sales;b.orders+=d.orders;buckets.set(label,b);}const bars=[...buckets.values()],max=Math.max(1,...bars.map(b=>b.sales));
 const trend=`<section class="panel"><div class="panel-head"><div><h2>Sales trends</h2><div class="muted">Net item sales before tax · ${r.days.length>31?'Monthly':'Daily'}</div></div></div><div class="panel-body">${bars.length?`<div class="sales-trend" role="img" aria-label="Sales by date">${bars.map(b=>`<div class="trend-column" title="${b.label}: ${money(b.sales)}, ${b.orders} invoices"><span>${money(b.sales)}</span><div class="trend-track"><div class="trend-bar" style="height:${Math.max(b.sales?2:0,b.sales/max*100)}%"></div></div><small>${b.label}</small></div>`).join('')}</div>`:'<div class="empty">Finalize an invoice to see your sales trends.</div>'}</div></section>`;
 $('content').innerHTML=`<section class="panel report-controls"><div class="panel-body"><div class="report-presets">${[['today','Today'],['week','Last 7 days'],['month','This month'],['all','All time']].map(([p,label])=>`<button onclick="reportPreset('${p}')">${label}</button>`).join('')}</div><div class="toolbar"><div><label for="report-from">From</label><input id="report-from" type="date" value="${esc(reportFrom)}" onchange="reportFrom=this.value;renderReports()"></div><div><label for="report-to">Through</label><input id="report-to" type="date" value="${esc(reportTo)}" onchange="reportTo=this.value;renderReports()"></div></div><p class="muted">Sales follow invoice creation dates. Collections follow payment dates. Invoice edits and deletions update these reports.</p>${reportFrom&&reportTo&&reportFrom>reportTo?'<p class="danger" role="alert">Choose an end date on or after the start date.</p>':''}</div></section><div class="report-tabs" role="group" aria-label="Report view">${[['summary','Sales summary'],['items','Item sales'],['payments','Payment methods']].map(([tab,label])=>`<button class="${reportTab===tab?'selected':''}" aria-pressed="${reportTab===tab}" onclick="reportTab='${tab}';renderReports()">${label}</button>`).join('')}</div><div class="metrics">${metric('Net sales',money(t.subtotal),'Item sales before tax')}${metric('Total collected',money(r.collected),'Payments recorded in this date range')}${metric('Invoice count',r.rows.length,'Finalized invoices')}${metric('Average sale',money(r.average),'Per invoice, including tax')}</div>${reportTab==='items'?`<section class="panel"><div class="panel-head"><h2>Item sales</h2><span class="badge">${t.packs} packs · ${t.units} units</span></div>${itemTable}</section>`:reportTab==='payments'?`<section class="panel"><div class="panel-head"><h2>Payment methods</h2><span class="badge">${money(r.collected)} recorded</span></div>${paymentTable}<div class="panel-body muted">Amounts are payment records entered in this app.</div></section>`:`${trend}<div class="report-detail-grid"><section class="panel"><div class="panel-head"><h2>Sales summary</h2></div><div class="panel-body">${details.map(([label,value])=>`<div class="total-row"><span>${label}</span><strong>${money(value)}</strong></div>`).join('')}<div class="total-row"><span>Items sold</span><strong>${t.units} units / ${t.packs} packs</strong></div></div></section><section class="panel"><div class="panel-head"><h2>Payment methods</h2></div>${paymentTable}</section></div><section class="panel"><div class="panel-head"><h2>Top items</h2><button onclick="reportTab='items';renderReports()">View all items</button></div>${reportTable(['Item','Packs','Net sales'],r.items.slice(0,5).map(p=>[esc(p.name),p.packs,money(p.sales)]))}</section>`}`;
}
function renderSettings(){const s=db.settings;$('content').innerHTML=`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Receipt setup</h2><span class="badge">Invoice only</span></div><div class="panel-body"><label for="business">Business name</label><input id="business" value="${esc(s.business)}"><label for="business-address">Business address</label><textarea id="business-address">${esc(s.address)}</textarea><label for="business-phone">Business phone</label><input id="business-phone" value="${esc(s.phone)}"><label for="receipt-footer">Custom footer text</label><textarea id="receipt-footer">${esc(s.footer)}</textarea><label for="receipt-extra">Additional receipt text</label><textarea id="receipt-extra" placeholder="Delivery terms, payment instructions, returns policy…">${esc(s.extra)}</textarea><div class="check" style="margin:18px 0"><input type="checkbox" id="show-barcode" ${s.showBarcode?'checked':''}><label for="show-barcode">Show product barcodes</label></div><div class="check"><input type="checkbox" id="show-notes" ${s.showNotes?'checked':''}><label for="show-notes">Show invoice notes</label></div><p class="muted">Receipts include customer details, pack sizes, volumes, total packs, total units, payments, and remaining balance. Tax ID is omitted.</p><button class="primary wide" onclick="saveSettings()">Save receipt settings</button></div></section><div>${window.CloudPOS?window.CloudPOS.card():''}<section class="panel" style="margin-bottom:22px"><div class="panel-head"><h2>Soda sugar tax</h2></div><div class="panel-body"><label for="default-tax">Default sugar tax per US fl oz ($)</label><input id="default-tax" type="number" min="0" step="0.000001" value="${(s.defaultSugarRateMicros/1000000).toFixed(6)}"><p class="muted">Used when creating products. Enter the applicable rate per US fluid ounce and enable it on soda products. Existing products can be edited individually.</p></div></section><section class="panel" style="margin-bottom:22px"><div class="panel-head"><h2>Printer & barcode scanner</h2></div><div class="panel-body"><h3>Print invoices</h3><p class="muted">Connect a printer supported by an Android print service. Use Preview & print on an invoice to select a printer or save a PDF. Only the invoice is sent to print.</p><button class="wide" onclick="deviceSettings('printers')">▧ Open printer settings</button><h3 style="margin-top:24px">Connect a scanner</h3><p class="muted">Tap the camera icon in Point of sale to scan with your camera, or use a USB or Bluetooth scanner in keyboard / HID mode. Set its suffix to Enter. Focus the Scan barcode field and scan. Save unknown barcodes through New product, then scan again to add that item.</p><button class="wide" onclick="deviceSettings('devices')">⌁ Pair Bluetooth scanner</button></div></section><section class="panel"><div class="panel-head"><h2>Data backup</h2></div><div class="panel-body"><p class="muted">Catalog and invoices are stored on this device. Copy a backup somewhere safe before uninstalling.</p><button class="wide" onclick="backupDialog()">Copy / restore backup</button></div></section></div></div>`;}
function saveSettings(){try{db.settings={business:$('business').value.trim()||'UBeer Wholesale',address:$('business-address').value.trim(),phone:$('business-phone').value.trim(),footer:$('receipt-footer').value,extra:$('receipt-extra').value,showBarcode:$('show-barcode').checked,showNotes:$('show-notes').checked,defaultSugarTax:0,defaultSugarRateMicros:C.rate($('default-tax').value)};if(persist())toast('Receipt and tax settings saved');}catch(e){toast(e.message);}}
function deviceSettings(type){if(window.NativePOS)NativePOS[type]();else toast('Device settings are available in the Android app. Pair keyboard scanners in your device settings.');}
function backupDialog(){modal('Backup & restore',`<p class="muted">Copy this JSON backup to a safe location. To restore, replace it with a previously saved backup. Restoring replaces all current data.</p><textarea id="backup" style="height:220px" spellcheck="false">${esc(JSON.stringify(db))}</textarea>`,`<div class="actions"><button onclick="$('backup').select()">Select all</button><button class="danger" onclick="restoreBackup()">Restore backup</button></div>`);}
function restoreBackup(){try{const data=JSON.parse($('backup').value);validateBackup(data);if(!confirm('Replace your current catalog, invoices, and settings with this backup?'))return;db=data;db.settings={...defaults,...db.settings};normalizeCategories(db);normalizeCustomers(db);current=db.draft||blankInvoice();db.draft=current;if(persist()){closeDialog();render();toast('Backup restored');}}catch(e){toast('Invalid backup: '+e.message);}}
function validateBackup(data){validateCustomerBackup(data);if(data.categories!==undefined&&(!Array.isArray(data.categories)||data.categories.some(c=>typeof c!=='string'||!c.trim()||c.length>60)))throw Error('Invalid categories');if(data.version!==1||!Array.isArray(data.products)||!Array.isArray(data.invoices)||!Number.isSafeInteger(data.nextNumber)||data.nextNumber<1)throw Error('Unsupported format');const ids=new Set();for(const p of data.products){if(typeof p.id!=='string'||!/^[a-zA-Z0-9-]+$/.test(p.id)||ids.has(p.id))throw Error('Invalid product ID');ids.add(p.id);if(typeof p.name!=='string'||typeof p.barcode!=='string'||typeof p.volume!=='string'||(typeof p.category!=='string'||!p.category.trim()))throw Error('Invalid product');C.validateProduct(p,data.products);}const invoiceIds=new Set();for(const i of [...data.invoices,...(data.draft?[data.draft]:[])]){if(typeof i.id!=='string'||!/^[a-zA-Z0-9-]+$/.test(i.id)||invoiceIds.has(i.id))throw Error('Invalid invoice ID');invoiceIds.add(i.id);if(!Array.isArray(i.lines)||!Array.isArray(i.payments)||!Array.isArray(i.history)||!i.customer||typeof i.customer.name!=='string'||!Number.isFinite(Date.parse(i.created)))throw Error('Invalid invoice');for(const l of i.lines){if(typeof l.name!=='string'||!Number.isSafeInteger(l.qty)||l.qty<1||!Number.isSafeInteger(l.price)||l.price<0||!Number.isSafeInteger(l.pack)||l.pack<1||!Number.isSafeInteger(l.sugarTax)||l.sugarTax<0)throw Error('Invalid invoice line');}for(const p of i.payments){if(!Number.isSafeInteger(p.amount)||p.amount<=0||!Number.isFinite(Date.parse(p.at)))throw Error('Invalid payment');}if(i.finalized&&(!Number.isSafeInteger(i.number)||i.number>=data.nextNumber))throw Error('Invalid invoice number');}}
$('today').textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});
render();persist();



function cameraIcon(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 7h4l2-3h4l2 3h4v13H4V7Z"/><circle cx="12" cy="13" r="4"/></svg>';}
function cameraScan(target='cart'){clearTimeout(scanTimer);document.activeElement?.blur();if(window.NativePOS?.scanBarcode){NativePOS.scanBarcode(target);}else{toast('Camera scanning is available in the Android app.');}}
window.onCameraBarcode=function(barcode,target='cart'){
 updateViewportHeight();
 if(typeof barcode!=='string'||!barcode.trim())return;
 clearTimeout(scanTimer);
 if(target==='product'&&$('dialog').open&&$('barcode')){$('barcode').value=barcode;toast('Barcode captured. Save the product to remember it.');return;}
 page='pos';query='';render();
 // Camera results only match a complete barcode, never a name or partial code.
 const matches=db.products.filter(p=>p.barcode&&C.norm(p.barcode)===C.norm(barcode));
 if(matches.length===1){addProduct(matches[0].id);return;}
 productEditor(null);$('barcode').value=barcode;toast('New barcode. Enter product details and save it.');
};



function setPhoneSaleView(view){phoneSaleView=view;clearTimeout(scanTimer);query='';renderPos();window.scrollTo?.({top:0,behavior:'smooth'});}

function updateViewportHeight(){
 const height=window.visualViewport?.height||window.innerHeight;
 if(height)document.documentElement.style.setProperty('--app-height',Math.round(height)+'px');
}
window.addEventListener?.('resize',updateViewportHeight);
window.visualViewport?.addEventListener('resize',updateViewportHeight);
updateViewportHeight();
document.addEventListener?.('keydown',event=>{if(event.key==='Escape'&&$('dialog').open){event.preventDefault();closeDialog();}});

function normalizeCategories(data){
 const names=[...(Array.isArray(data.categories)?data.categories:['Beer','Soda','Water','Other']),...data.products.map(p=>p.category)];
 const seen=new Set();data.categories=names.filter(c=>{if(typeof c!=='string'||!c.trim()||seen.has(C.norm(c))||C.norm(c)==='all products')return false;seen.add(C.norm(c));return true;});
}
function selectCategory(index){category=['All products',...db.categories][index]||'All products';renderProductGrid();renderFilters();}
function categoryManager(){
 modal('Product categories',`<p class="muted">Add categories to organize products and filter your sales catalog.</p><label for="new-category">New category name</label><div class="category-create"><input id="new-category" maxlength="60" placeholder="e.g. Juice, Snacks, Energy drinks"><button class="primary" onclick="addCategory()">＋ Add</button></div><div class="category-list">${db.categories.map(c=>`<div class="total-row"><strong>${esc(c)}</strong><span class="muted">${db.products.filter(p=>p.category===c).length} products</span></div>`).join('')}</div>`,`<div class="actions"><button onclick="closeDialog()">Done</button></div>`);
}
function addCategory(inProduct=false){
 const name=$('new-category').value.trim();
 if(!name||name.length>60){toast('Enter a category name from 1 to 60 characters.');return;}
 if(C.norm(name)==='all products'||db.categories.some(c=>C.norm(c)===C.norm(name))){toast('That category already exists. Choose another name.');return;}
 db.categories.push(name);if(!persist()){db.categories.pop();return;}
 if(inProduct){const select=$('category');select.innerHTML=db.categories.map(c=>`<option value="${esc(c)}" ${c===name?'selected':''}>${esc(c)}</option>`).join('');select.value=name;$('new-category').value='';}
 else{render();categoryManager();}
 toast('Category added');
}


function sugarRateLabel(p){return !p.soda?'$0':p.sugarRateMicros!=null?'$'+(p.sugarRateMicros/1000000).toFixed(6)+' / oz':money(p.sugarTax)+' / pack (legacy)';}



function prepareNumberInputs(scope){
 for(const input of scope.querySelectorAll?.('input[type="number"], input[data-numeric], #barcode, #volume')||[]){
  if(input.dataset.replaceReady)continue;
  if(input.type==='number'){
   input.dataset.numeric='true';input.inputMode=input.step==='1'?'numeric':'decimal';input.type='text';
  }
  input.dataset.replaceReady='true';
  input.addEventListener('focus',()=>{input.select();});
  input.addEventListener('click',()=>{input.select();});
 }
}

function productMenu(p,inTable=false){if(inTable)return `<button class="more-button" title="Product options" aria-label="Options for ${esc(p.name)}" onclick="productActions('${p.id}')">⋮</button>`;return `<div class="product-more"><button class="more-button" aria-label="Options for ${esc(p.name)}" aria-expanded="false" onclick="toggleProductMenu(this)">⋮</button><div class="product-menu" hidden><button onclick="closeProductMenus();productEditor('${p.id}')">✎ Edit product</button><button class="danger" onclick="deleteProduct('${p.id}')">✕ Remove product</button></div></div>`;}
function productActions(id){const p=db.products.find(p=>p.id===id);if(!p)return;modal('Product options',`<p><strong>${esc(p.name)}</strong></p><button class="wide" onclick="productEditor('${id}')">✎ Edit product</button><button class="wide danger" onclick="deleteProduct('${id}')">✕ Remove product</button>`,`<div class="actions"><button onclick="closeDialog()">Cancel</button></div>`);}
function closeProductMenus(){document.querySelectorAll('.product-menu').forEach(menu=>{menu.hidden=true;menu.previousElementSibling?.setAttribute('aria-expanded','false');});}
function toggleProductMenu(button){const menu=button.nextElementSibling,wasOpen=!menu.hidden;closeProductMenus();if(!wasOpen){menu.hidden=false;button.setAttribute('aria-expanded','true');}}
document.addEventListener?.('click',event=>{if(!event.target.closest('.product-more'))closeProductMenus();});
document.addEventListener?.('keydown',event=>{if(event.key==='Escape')closeProductMenus();});


let customerQuery='';
function customerIdentity(c){return ['name','phone','email','address','taxId'].map(k=>C.norm(c[k]||'')).join('|');}
function normalizeCustomers(data){
 if(!Array.isArray(data.customers))data.customers=[];
 for(const invoice of [...data.invoices,...(data.draft?[data.draft]:[])]){
  const c=invoice.customer;if(!c?.name?.trim())continue;
  if(invoice.customerId&&data.customers.some(x=>x.id===invoice.customerId))continue;
  let record=data.customers.find(x=>customerIdentity(x)===customerIdentity(c));
  if(!record){record={id:uid(),name:c.name,phone:c.phone||'',email:c.email||'',address:c.address||'',taxId:c.taxId||'',updated:invoice.updated||invoice.created};data.customers.push(record);}
  invoice.customerId=record.id;
 }
}
function renderCustomers(){
 $('content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Customer database</h2><div class="muted">${db.customers.length} saved customers · Find and reuse customer information</div></div><button class="primary" onclick="customerEditor(null,true)">＋ Add customer</button></div><div class="panel-body"><div class="customer-search-controls"><input id="customer-search" aria-label="Search customers" placeholder="Search name, phone, email, or address…" value="${esc(customerQuery)}" oninput="customerQuery=this.value;renderCustomerList('customer-list')"><button onclick="clearCustomerSearch(false)">Clear</button></div></div><div id="customer-list"></div></section>`;
 renderCustomerList('customer-list');
}
function clearCustomerSearch(picker=false){customerQuery='';$('customer-search').value='';renderCustomerList(picker?'customer-picker-list':'customer-list',picker);}
function customerPicker(){
 modal('Find previous customer',`<label for="customer-search">Search saved customers</label><div class="customer-search-controls"><input id="customer-search" placeholder="Name, phone, email, or address…" value="${esc(customerQuery)}" oninput="customerQuery=this.value;renderCustomerList('customer-picker-list',true)"><button onclick="clearCustomerSearch(true)">Clear</button></div><div id="customer-picker-list"></div>`,`<div class="actions"><button onclick="customerEditor()">Enter customer manually</button><button onclick="closeDialog()">Cancel</button></div>`);
 renderCustomerList('customer-picker-list',true);
}
function renderCustomerList(target,picker=false){
 const rows=db.customers.filter(c=>C.norm([c.name,c.phone,c.email,c.address].join(' ')).includes(C.norm(customerQuery))).sort((a,b)=>a.name.localeCompare(b.name));
 $(target).innerHTML=rows.length?rows.map(c=>{
  const invoices=db.invoices.filter(i=>i.customerId===c.id),balance=invoices.reduce((sum,i)=>sum+C.totals(i).balance,0);
  return `<div class="customer-row"><div><strong>${esc(c.name)}</strong><div class="muted">${esc([c.phone,c.email].filter(Boolean).join(' · '))}</div><div class="muted">${esc(c.address)}</div><div class="muted">${invoices.length} invoices · Balance ${money(balance)}</div></div><div class="customer-actions"><button class="primary" onclick="useCustomer('${c.id}')">Select</button>${picker?'':`<button onclick="customerEditor('${c.id}',true)">Edit</button><button onclick="customerHistory('${c.id}')">History</button>`}</div></div>`;
 }).join(''):'<div class="empty">No matching customers. Save customer information to add a record.</div>';
}
function useCustomer(id){
 const c=db.customers.find(c=>c.id===id);if(!c)return;
 current.customer={name:c.name,phone:c.phone,email:c.email,address:c.address,taxId:c.taxId};current.customerId=c.id;
 saveCurrent('Selected saved customer');closeDialog();page='pos';phoneSaleView='cart';render();toast('Customer selected');
}
function customerHistory(id){
 const c=db.customers.find(c=>c.id===id);if(!c)return;
 const invoices=db.invoices.filter(i=>i.customerId===id).slice().reverse();
 modal('Customer invoice history',`<p><strong>${esc(c.name)}</strong></p>${invoices.length?invoices.map(i=>`<div class="customer-row"><div><strong>Invoice #${i.number}</strong><div class="muted">${date(i.created)} · Total ${money(C.totals(i).total)} · Balance ${money(C.totals(i).balance)}</div></div><button onclick="closeDialog();openInvoice('${i.id}')">Open</button></div>`).join(''):'<div class="empty">No finalized invoices for this customer yet.</div>'}`,`<div class="actions"><button onclick="closeDialog()">Done</button></div>`);
}

function validateCustomerBackup(data){
 if(data.customers===undefined)return;
 if(!Array.isArray(data.customers))throw Error('Invalid customer database');
 const ids=new Set();for(const c of data.customers){
  if(!c||typeof c.id!=='string'||!/^[a-zA-Z0-9-]+$/.test(c.id)||ids.has(c.id)||typeof c.name!=='string'||!c.name.trim())throw Error('Invalid customer record');
  ids.add(c.id);for(const field of ['phone','email','address','taxId'])if(typeof c[field]!=='string')throw Error('Invalid customer information');
 }
}
